old_handle="""  function handleLobbyMessage(message){
    if(message.type==='connected'){if(message.account){account={...account,...message.account};renderAccountBox();}return;}
    if(message.type==='recommendations'||message.type==='searchResults'){renderPlayers(message.players||[]);return;}
    if(message.type==='challengeSent'){$('lobbyStatus').textContent=`Waiting for ${message.to?.nickname||'player'} to respond…`;return;}
    if(message.type==='playRequest'){pendingRequest=message;const from=message.from||{};$('requestPlayerName').textContent=`${flagEmoji(from.countryCode)} ${from.nickname||'Player'} wants to play GoStop with you.`;$('requestPlayerStats').textContent=`${from.rank?`Rank #${from.rank} · `:''}Score ${fmtScore(from.score)} · ${from.gamesPlayed||0} games · ${from.walletCoins||0} Coins`;if(!requestDialog.open)requestDialog.showModal();return;}
    if(message.type==='challengeAcceptedCreateRoom'){pendingChallengeCreate=message.requestId;$('lobbyStatus').textContent='Accepted — creating the game room…';onlinePanel.hidden=true;createRoom?.click();return;}
    if(message.type==='challengeAcceptedWaiting'){$('lobbyStatus').textContent='Accepted — waiting for the other player to create the room…';return;}
    if(message.type==='challengeRoomReady'){const input=$('onlineRoomCode');if(!input||!joinForm)return;input.value=message.roomCode;onlinePanel.hidden=true;joinForm.requestSubmit();return;}
    if(message.type==='challengeRoomHandoffComplete'){pendingChallengeCreate=null;onlinePanel.hidden=true;return;}
    if(message.type==='challengeDeclined'){$('lobbyStatus').textContent=`${message.by?.nickname||'Player'} declined the request.`;requestRecommendations();return;}
    if(message.type==='challengeCancelled'||message.type==='challengeError'){pendingChallengeCreate=null;$('lobbyStatus').textContent=message.message||'The play request could not be completed.';requestRecommendations();return;}
  }"""
